INSERT  IGNORE INTO `candidates` (`id`, `created_at`, `education`, `email`, `experience_years`, `extracted_skills`, `name`, `phone`, `resume_filename`, `resume_text`) VALUES (1,'2026-06-16 08:44:52.174263','Bachelor of Technology in Information Technology (In Progress)','srihari2007sa@gmail.com',0,'C, C++, Java, Python, SQL, HTML, CSS, JavaScript, Data Structures & Algorithms, Operating Systems, Database Management System, Object Oriented Programming, JDBC, Web Development','Sri Hari','+91-8778990775','SRI HARI-RESUME.pdf','\nSRI HARI\nBHAVANI,TAMIL NADU\n\nÓ +91-8778990775  srihari2007sa@gmail.com  SRI HARI � SRI HARI Ã SRI HARI � SRI HARI\n\nEDUCATION\n\nKarpagam Institute of Technology 2024 - Present\n\nBachelor of Technology - Information Technology - CGPA - 7.62 Coimbatore, India\n\nRoyal International Senior Secondary School-CBSE 2023 - 2024\n\nSenior Secondary - Percentage - 63.8% Komarapalayam, India\n\nCOURSEWORK / SKILLS\n\n• Data Structures & Algorithms\n\n• Operating Systems\n\n• Object Oriented Programming\n\n• Problem Solving\n\n• Web Development\n\n• Database Management System\n\nPROJECTS\n\nMovie Ticket Booking System | Java, SQL, JDBC 2025\n\n• Built a console-based movie ticket booking application with seat selection, booking, and cancellation. Designed\nrelational database schema for movies, shows, seats, and bookings and integrated using JDBC. Implemented\ntransaction handling and input validation to ensure data consistency.\n\nTicket Reservation System | Java, SQL 2025\n\n• Developed a reservation system providing real-time seat availability and instant booking confirmation.\nDesigned ER and class diagrams and enforced database constraints for users, tickets, routes, and payments.\nReduced booking errors through backend validation and structured database design.\n\nSmart Traffic Signal Controller (Simulation) | C++ / Java, Algorithms 2025\n\n• Implemented a smart traffic signal simulation with dynamic signal time allocation based on traffic density.\nUsed a greedy proportional algorithm to distribute signal time and simulate vehicle clearance per cycle.\nGenerated cycle-wise and cumulative traffic statistics for performance analysis.\n\nTECHNICAL SKILLS\n\nLanguages: C, C++, Java, Python, SQL\nWeb Technologies: HTML, CSS, JavaScript\n\nEXTRACURRICULAR/SOFT SKILLS\n\nDakshin Bharat Hindi Prachar Sabha\nHindi Language Certification Candidate\n\n• Completed 6 out of 8 structured Hindi language examinations, demonstrating progressive proficiency in\nreading, writing, and grammar.\n\nCERTIFICATIONS\n\n• C, C++, Core Java & Python with Data Science –\nCode Galatta\n\n• Introduction to SQL – Simplilearn\n\n• Master C++ for Competitive Coding – AlgoZenith\n\n• Problem Solving (Basic) – HackerRank\n\ntel:+91-8778990775\nsrihari2007sa@gmail.com\nhttps://linkedin.com/in/srihari2007sa\nhttps://github.com/srihari2007sa\nhttps://www.hackerrank.com/srihari2007sa\nhttps://codeforces.com/profile/srihari2007sa\nProjectLink.com\nProjectLink.com\nProjectLink.com\n\n	EDUCATION\n	COURSEWORK / SKILLS\n	PROJECTS\n	TECHNICAL SKILLS\n	EXTRACURRICULAR/SOFT SKILLS\n	CERTIFICATIONS\n\n');
