INSERT  IGNORE INTO `screening_results` (`id`, `ai_strengths`, `ai_summary`, `ai_weaknesses`, `match_score`, `match_status`, `screened_at`, `screening_mode`, `suggested_questions`, `candidate_id`, `job_description_id`, `career_dna_profile`, `recruiter_notes`) VALUES (1,'Demonstrates strong foundational technical skills in multiple required languages (Java, C++, C, Python, SQL).\nRelevant project experience applying core SDE concepts (DBMS, transaction handling, algorithms) using required technologies.\nCoursework covers key areas like Data Structures & Algorithms, Operating Systems, and Database Management Systems.\nMatches the \'0 years\' minimum experience requirement, indicating suitability for an entry-level role.\nCertifications validate proficiency in C, C++, Core Java, Python, and SQL.','Sri Hari is an early-career candidate demonstrating a strong foundation in core programming languages such as Java, C++, C, and Python, along with practical experience in Operating Systems and Database Management Systems through coursework and well-described projects. While meeting the \'0 years\' experience requirement, the candidate is currently pursuing a Bachelor\'s Degree and has not yet completed it, which is a critical gap against the job\'s minimum education requirement.','Does not meet the \'Bachelor\'s Degree\' minimum education requirement, as the candidate is currently pursuing their degree and is likely in their early academic years (started 2024).\nNo professional work experience (internships, full-time roles) is explicitly mentioned.\nThe \'COMMUNICATION\' skill is required but not explicitly demonstrated or quantified in the resume.',65,'Under Review','2026-06-16 08:45:10.057234','GEMINI_AI','The job description requires a completed Bachelor\'s Degree. Can you elaborate on your current academic status and expected graduation timeline?\nCould you walk us through the design choices and technical challenges you faced while developing the \'Smart Traffic Signal Controller\' simulation?\nGiven your experience with Java and SQL in your projects, describe a time you optimized a database query or managed data consistency in a multi-user environment.\nHow do you approach learning new technologies or concepts that are critical for a project but outside your current coursework?\nCan you provide an example from your academic projects or extracurriculars where you had to effectively communicate a technical concept to a non-technical audience or team member?',1,1,NULL,NULL);
INSERT  IGNORE INTO `screening_results` (`id`, `ai_strengths`, `ai_summary`, `ai_weaknesses`, `match_score`, `match_status`, `screened_at`, `screening_mode`, `suggested_questions`, `candidate_id`, `job_description_id`, `career_dna_profile`, `recruiter_notes`) VALUES (2,'Strong foundational skills in all required programming languages (Java, C++, C, Python) and core computer science concepts (OS, DBMS, DSA, OOP).\nPractical experience demonstrated through relevant projects applying SDE principles like database design, transaction handling, and algorithm implementation.\nProactive in skill development, evidenced by numerous technical certifications and competitive programming profiles (HackerRank, Codeforces).\nMeets all minimum experience (0 years) and education requirements for an entry-level SDE role.','A highly motivated and skilled entry-level Software Development Engineer candidate with a strong foundational knowledge in core programming languages like Java, C++, C, and Python. Demonstrates practical application of technical skills through relevant projects in database management, operating systems, and algorithms, complemented by multiple certifications and a proactive learning approach.','Lack of professional work experience (though expected for a \'0 years\' role).\nCommunication skill is inferred from language certification rather than direct professional or team-based communication examples.\nAmbiguity in project dates (2025) while education is listed as \'2024 - Present\' might require clarification on the completion status of projects.',92.5,'Shortlisted','2026-06-17 04:03:10.133406','GEMINI_AI','Could you elaborate on the specific challenges you faced while designing the relational database schema for the \'Movie Ticket Booking System\' and how you resolved them?\nGiven your experience with various programming languages, how do you decide which language is most suitable for a new project, and what are your preferences for different types of applications?\nThe job involves working with operating systems; can you describe a scenario where understanding OS concepts was critical to solving a problem in one of your projects?\nThe job requires strong communication skills. Can you provide an example of a time you had to explain a complex technical concept to someone with a non-technical background?',1,1,NULL,NULL);
INSERT  IGNORE INTO `screening_results` (`id`, `ai_strengths`, `ai_summary`, `ai_weaknesses`, `match_score`, `match_status`, `screened_at`, `screening_mode`, `suggested_questions`, `candidate_id`, `job_description_id`, `career_dna_profile`, `recruiter_notes`) VALUES (5,'Strong command of required programming languages (Java, C++, C, Python) and foundational concepts (Operating Systems, DBMS, DSA).\nRelevant project experience demonstrating practical application of technical skills and problem-solving.\nProactive learning indicated by multiple certifications in key technologies.\nPursuing a Bachelor\'s degree in Information Technology, meeting the educational requirement.\nIdeal fit for a 0-years experience entry-level SDE position.','Sri Hari is an excellent candidate for an entry-level Software Development Engineer role, demonstrating a strong foundation in core programming languages like Java, C++, C, and Python, alongside robust knowledge in Operating Systems and Database Management. Currently pursuing a Bachelor\'s degree, their resume highlights practical application through relevant projects such as a Movie Ticket Booking System and Smart Traffic Signal Controller, perfectly aligning with the job\'s 0 years experience requirement.','Lack of formal professional work experience (standard for a fresher, but noted).\nLimited insight into practical experience with version control, collaborative development, or production deployments.\nSoft skill assessment (e.g., \'COMMUNICATION\') is difficult solely from the resume.',92.5,'Shortlisted','2026-06-17 06:17:44.280763','GEMINI_AI','Describe your approach to designing the database schema for your Ticket Reservation System and any challenges you faced during its implementation.\nIn your Smart Traffic Signal Controller project, how did you choose and implement the greedy proportional algorithm, and what were the outcomes?\nGiven your project experience, how do you approach debugging complex code, and what tools or techniques do you find most effective?\nThe job requires strong communication skills. Can you provide an example from your academic or project work where effective communication was crucial for success?',1,1,NULL,NULL);
INSERT  IGNORE INTO `screening_results` (`id`, `ai_strengths`, `ai_summary`, `ai_weaknesses`, `match_score`, `match_status`, `screened_at`, `screening_mode`, `suggested_questions`, `candidate_id`, `job_description_id`, `career_dna_profile`, `recruiter_notes`) VALUES (11,'Strong command of required programming languages (Java, C, C++, Python, SQL) and related technical concepts (Data Structures & Algorithms, OS, DBMS).\nDemonstrated practical application of skills through multiple relevant academic projects.\nProactive in skill development, evidenced by several technical certifications.\nMeets the 0 years professional experience requirement.','Sri Hari is an enthusiastic candidate with a strong foundational understanding and practical skills in core programming languages (Java, C, C++, Python) and essential computer science concepts such as Data Structures & Algorithms, Operating Systems, and Database Management Systems. This is evidenced by multiple relevant academic projects and technical certifications. While meeting the 0 years experience requirement, the candidate is currently pursuing a Bachelor\'s Degree and has not yet achieved the minimum required education.','Does not currently possess the \"Required Min Education: Bachelor\'s Degree\"; currently pursuing this degree, with Senior Secondary as the highest achieved education.\nLack of professional work experience (internship/full-time).\nCommunication skills not explicitly demonstrated in a professional context.\nThe timeline for the Bachelor\'s degree (2024-Present, with 2025 projects) suggests an early stage of study, which might impact immediate full-time employment availability.',70,'Shortlisted','2026-07-06 06:33:55.297875','GEMINI_AI','Could you clarify your current academic status and your expected graduation date for your Bachelor of Technology degree?\nGiven that the role requires a Bachelor\'s Degree, how do you plan to meet this requirement while also performing the duties of a Software Development Engineer?\nCan you elaborate on your experience with JDBC in the Movie Ticket Booking System and how you ensured transaction handling and data consistency?\nHow do you manage concurrent access or potential race conditions in your Ticket Reservation System?\nThe job description requires strong communication skills. Can you describe a situation where you effectively communicated a complex technical idea to a non-technical audience or collaborated on a project?',1,1,NULL,NULL);
INSERT  IGNORE INTO `screening_results` (`id`, `ai_strengths`, `ai_summary`, `ai_weaknesses`, `match_score`, `match_status`, `screened_at`, `screening_mode`, `suggested_questions`, `candidate_id`, `job_description_id`, `career_dna_profile`, `recruiter_notes`) VALUES (12,'Comprehensive technical skill set closely aligned with job requirements (Java, C++, C, Python, Operating Systems, Database Management System).\nRelevant academic projects demonstrating practical application of key technologies (Java, SQL, C++).\nMultiple certifications validating programming proficiency and problem-solving abilities.\nMeets the minimum experience requirement of 0 years.','Sri Hari demonstrates a strong foundational skill set in core programming languages (Java, C++, Python) and fundamental SDE concepts such as Operating Systems and Database Management, supported by coursework, projects, and certifications. While meeting the 0 years experience requirement, the candidate is currently pursuing a Bachelor\'s degree (2024-Present) which does not meet the \'Bachelor\'s Degree\' education requirement. Additionally, project dates listed as 2025 raise concerns regarding their current completion status and the resume\'s accuracy.','Does not meet the \'Bachelor\'s Degree\' education requirement as the degree is currently in progress (2024-Present), indicating they are early in their studies.\nProject dates (2025) are inconsistent with current year (2024) and education timeline, raising questions about project completion status or resume accuracy.\nLimited explicit demonstration of professional communication skills beyond language certification.',65,'Under Review','2026-07-06 06:44:05.412240','GEMINI_AI','Can you clarify your expected graduation date for the Bachelor of Technology degree and how it aligns with your availability for a full-time role?\nThe projects listed are dated 2025. Could you explain the current status of these projects and your contribution to them given the dates?\nDescribe a challenging technical problem you\'ve encountered in your projects or coursework and how you approached solving it.',1,1,NULL,NULL);
INSERT  IGNORE INTO `screening_results` (`id`, `ai_strengths`, `ai_summary`, `ai_weaknesses`, `match_score`, `match_status`, `screened_at`, `screening_mode`, `suggested_questions`, `candidate_id`, `job_description_id`, `career_dna_profile`, `recruiter_notes`) VALUES (13,'Strong proficiency in core programming languages including Java, C++, C, and Python, directly matching job requirements.\nDemonstrated practical application of skills through multiple relevant projects (Movie Ticket Booking, Ticket Reservation, Smart Traffic Signal Controller) using required technologies like Java, SQL, and C++.\nSolid foundational knowledge in Data Structures & Algorithms, Operating Systems, and Database Management Systems.\nPossesses numerous relevant technical certifications validating skills in C, C++, Java, Python, SQL, and Problem Solving.\nMeets the minimum experience requirement for a 0-year role and shows strong initiative for a junior position.','Sri Hari is a highly promising candidate for a Software Development Engineer role, demonstrating strong proficiency in multiple required programming languages and foundational computer science concepts. Despite having no professional experience and an ongoing degree, the candidate showcases significant practical application through relevant projects and numerous technical certifications, making them an excellent fit for a 0-year experience role.','The required \'COMMUNICATION\' skill is not explicitly detailed or demonstrated in a professional context in the resume.\nEducation (Bachelor of Technology) is currently in progress, not yet completed.\nNo professional work experience listed, though this aligns with the job\'s 0-year experience requirement for an entry-level role.',92.5,'Shortlisted','2026-07-11 10:02:48.962757','GEMINI_AI','Can you describe a situation where you had to communicate a complex technical concept or project detail to a non-technical audience or team member?\nWalk us through the design and implementation of one of your projects, focusing on a specific challenge you faced and how you resolved it.\nGiven that your Bachelor\'s degree is still in progress, how do you plan to manage your academic commitments alongside a full-time SDE role?\nHow do you approach learning new programming languages or technologies, and what is a recent example of something new you\'ve learned on your own?',1,1,'{\"archetypeDescription\":\"Primarily a Data & ML Engineer with strong secondary capabilities in Frontend Craftsman. This candidate brings focused depth in their core domain while maintaining cross-functional versatility.\",\"archetypeScores\":{\"Security Engineer\":0,\"Frontend Craftsman\":23,\"Cloud & DevOps\":0,\"Backend Architect\":14,\"Technical Leader\":0,\"Mobile Developer\":0,\"Data & ML Engineer\":24,\"Database Specialist\":15},\"dominantArchetype\":\"Data & ML Engineer\",\"dnaStrength\":10,\"secondaryArchetype\":\"Frontend Craftsman\"}',NULL);
