INSERT  IGNORE INTO `screening_results` (`id`, `ai_strengths`, `ai_summary`, `ai_weaknesses`, `match_score`, `match_status`, `screened_at`, `screening_mode`, `suggested_questions`, `candidate_id`, `job_description_id`, `career_dna_profile`, `recruiter_notes`) VALUES (23,'Complete technical stack match including Java, C++, Python, Operating Systems, and DBMS\nPractical application of skills demonstrated through functional academic projects\nActive continuous learning evidenced by multiple certifications from HackerRank, Simplilearn, and AlgoZenith','Sri Hari is an entry-level candidate currently pursuing a B.Tech in Information Technology with a strong foundational alignment with the required SDE skills. They have completed multiple relevant projects in Java and C++ and hold verified technical certifications. However, their degree is still in progress (commenced in 2024), which may affect their immediate availability for a full-time role.','Bachelor\'s degree is currently in progress and not yet completed\nNo prior professional industry or internship experience',74,'Under Review','2026-07-13 05:44:33.051271','GEMINI_AI','What is your expected graduation timeline, and what is your current availability for this Software Development Engineer position?\nCan you walk me through the database schema and transaction handling mechanism you designed for your Movie Ticket Booking System?\nHow does the greedy proportional algorithm in your Smart Traffic Signal Controller determine dynamic signal time?',1,1,'{\"archetypeDescription\":\"Primarily a Data & ML Engineer with strong secondary capabilities in Frontend Craftsman. This candidate brings focused depth in their core domain while maintaining cross-functional versatility.\",\"archetypeScores\":{\"Security Engineer\":0,\"Frontend Craftsman\":23,\"Cloud & DevOps\":0,\"Backend Architect\":14,\"Technical Leader\":0,\"Mobile Developer\":0,\"Data & ML Engineer\":24,\"Database Specialist\":15},\"dominantArchetype\":\"Data & ML Engineer\",\"dnaStrength\":10,\"secondaryArchetype\":\"Frontend Craftsman\"}',NULL);
